#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzSample_heightMap(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_heightMap(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_heightSource;
uniform float amzp_heightScale;
uniform float amzp_bumpIntensity;
uniform float amzp_normalRes;
uniform float amzp_quality;
uniform float amzp_lightType;
uniform float2 amzp_lightDir;
uniform float amzp_lightDepth;
uniform float amzp_lightIntensity;
uniform float amzp_ambient;
uniform float amzp_roughness;
uniform float amzp_specularIntensity;
layout(color) uniform half4 amzp_specularTint;
uniform float amzp_preserveAlpha;
uniform float amzp_unpremultBeforeShade;
uniform float amzp_exposure;

    const float3 W = float3(0.2126, 0.7152, 0.0722);

    float luma(float3 c){ return dot(c, W); }

    float heightAt(float2 uv){
      if (int(amzp_heightSource) == 1) {
        float4 h = amzTexture(1, uv);
        return luma(h.rgb) * amzp_heightScale;
      }
      float4 s = amzTexture(0, uv);
      return luma(s.rgb) * amzp_heightScale;
    }

    float3 computeNormal(float2 uv, float2 texel, float radius){
      float r = radius;
      if (int(amzp_quality) == 1) {

        float tl = heightAt(uv + float2(-texel.x,  texel.y) * r);
        float tc = heightAt(uv + float2( 0.0     ,  texel.y) * r);
        float tr = heightAt(uv + float2( texel.x ,  texel.y) * r);
        float ml = heightAt(uv + float2(-texel.x,  0.0    ) * r);
        float mr = heightAt(uv + float2( texel.x ,  0.0    ) * r);
        float bl = heightAt(uv + float2(-texel.x, -texel.y) * r);
        float bc = heightAt(uv + float2( 0.0     , -texel.y) * r);
        float br = heightAt(uv + float2( texel.x , -texel.y) * r);
        float dx = (tr + 2.0*mr + br) - (tl + 2.0*ml + bl);
        float dy = (tl + 2.0*tc + tr) - (bl + 2.0*bc + br);
        return normalize(float3(-dx * amzp_bumpIntensity, -dy * amzp_bumpIntensity, 1.0));
      } else {

        float hR = heightAt(uv + float2(texel.x * r, 0.0));
        float hL = heightAt(uv - float2(texel.x * r, 0.0));
        float hU = heightAt(uv + float2(0.0, texel.y * r));
        float hD = heightAt(uv - float2(0.0, texel.y * r));
        float dx = (hR - hL);
        float dy = (hU - hD);
        return normalize(float3(-dx * amzp_bumpIntensity, -dy * amzp_bumpIntensity, 1.0));
      }
    }

    float shininessFromRoughness(float r){

      return mix(256.0, 8.0, clamp(r, 0.0, 1.0));
    }

    void amzRender(){
      float2 uv = amzScreenNorm();
      float2 texel = 1.0 / screen.zw;

      float4 base = amzTexture(0, uv);
      float4 src = base;
      if ((amzp_unpremultBeforeShade>0.5) && src.a > 0.0) src.rgb /= src.a;


      float3 n = computeNormal(uv, texel, amzp_normalRes);


      float3 V = float3(0.0, 0.0, 1.0);
      float3 L;
      if (int(amzp_lightType) == 1) {

        float3 lightPos = float3(amzp_lightDir.x / 2.0, -amzp_lightDir.y / 2.0, -amzp_lightDepth * 0.02);
        float3 p = float3(uv * 2.0 - 1.0, 0.0);
        L = normalize(lightPos - p);
      } else {

        L = normalize(float3(amzp_lightDir.x, -amzp_lightDir.y, amzp_lightDepth));
      }

      float diff = max(dot(n, L), 0.0) * amzp_lightIntensity;

      float3 H = normalize(L + V);
      float specPow = shininessFromRoughness(amzp_roughness);
      float spec = pow(max(dot(n, H), 0.0), specPow) * amzp_specularIntensity;


      float amb = amzp_ambient;
      float3 lit = src.rgb * (amb + diff * (1.0 - amb));
      lit += amzp_specularTint.rgb * spec;
      lit *= amzp_exposure;

      float4 outC = float4(lit, src.a);
      if ((amzp_unpremultBeforeShade>0.5) && src.a > 0.0) outC.rgb *= src.a;
      if ((amzp_preserveAlpha>0.5)) outC.a = base.a;
      amzOutput = outC;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

